function symbolFromRect(source,x,y,w,h,day){const thumb=document.createElement('canvas');thumb.width=48;thumb.height=48;const t=thumb.getContext('2d');t.fillStyle='#fff';t.fillRect(0,0,48,48);t.drawImage(source,x,y,w,h,0,0,48,48);const f=document.createElement('canvas');f.width=f.height=20;const fc=f.getContext('2d',{willReadFrequently:true});fc.fillStyle='#fff';fc.fillRect(0,0,20,20);const inset=0;fc.drawImage(source,x+w*inset,y+h*inset,w*(1-2*inset),h*(1-2*inset),0,0,20,20);const pixels=fc.getImageData(0,0,20,20).data;const feature=[];for(let i=0;i<pixels.length;i+=4)feature.push(pixels[i],pixels[i+1],pixels[i+2]);return{day,thumb:thumb.toDataURL('image/png'),feature}}
