  const placements=state.pdfPage?imagesAtCell(state.placements,r,i+1,days()):[];
  if(placements.length>4){notice('Mehr als vier Dienste in einem Tagesfeld. Bitte den Ausschnitt prüfen.','error');return}
  const parts=placements.length?placements:[null],note=mergeDutyNotes(below[i],rasterNote(i,r,placements));
