   const placement=parts[part];let cell=null;
   if(placement){try{const image=state.pdfPage.objs.get(placement.id),c=document.createElement('canvas');c.width=image.width;c.height=image.height;const cx=c.getContext('2d');if(image.bitmap)cx.drawImage(image.bitmap,0,0);else cx.putImageData(new ImageData(pixelRGBA(image),image.width,image.height),0,0);cell=symbolFromRect(c,0,0,c.width,c.height,i+1)}catch{}}
