   const cx=placement?placement.x+placement.w/2:r.x+(i+.5)*r.w/days(),width=placement?placement.w:r.w/days();
   const printed=state.items.filter(t=>Math.abs(t.x+t.width/2-cx)<width*.48&&t.y>=r.y&&t.y<=r.y+r.h).map(t=>t.text.trim()).filter(t=>/^[A-ZÄÖÜ][A-Za-zÄÖÜäöü.]{0,3}$/.test(t));
