 if(allValid()){goto(3);notice((zgks.enabled?'ZGKS-Legende angewendet. ':'')+'Deine Zeile und alle Dienstsymbole wurden erkannt. Bitte prüfe die Dienste vor dem Export.','success');return}
 goto(2);notice(`${state.groups.filter(g=>!validateDefinition(g.definition)).length} noch offene Dienste für ${days()} Tage. Freie Felder und bereits hinterlegte Dienste werden automatisch übersprungen.`);
