 for(const [kind,title]of[['presence','Dienste'],['absence','Absenzen und freie Tage']]){const options=document.createElement('optgroup');options.label=title;for(const ref of [...zgksRegistry.symbols,...strokeLegend(zgksRegistry)].filter(r=>r.kind===kind)){const time=ref.type==='shift'?ref.start+'–'+ref.end:ref.type==='allday'?'ganztägig':'kein Eintrag';options.append(new Option(ref.code+' · '+ref.name+' · '+time,ref.id))}select.append(options)}
