 const box=document.createElement('div');box.className='info-box';const text=document.createElement('p');text.textContent='Dein Plan liegt vor dem Gültigkeitsbeginn der hinterlegten Legende. Die Präsenzzeiten gelten laut Dokument ab 01.01.2027, die Absenz-Legende ab 01.10.2026. Wenn die Angaben bereits für diesen Plan gelten, kannst du sie hier gemeinsam übernehmen.';box.append(text);
