$('#forget-profile').onclick=()=>{localStorage.removeItem('schichtkompass-legend-v1');state.profile=[];$('#remember').checked=false;notice('Die gespeicherte Legende wurde von diesem Gerät gelöscht. Aktuell ausgefüllte Felder bleiben bis zum Leeren der Sitzung bestehen.','success')};
async function openCatalog(){if(zgks.enabled){openZGKSLegend();return;}try{if(!state.catalog.length){const refs=await loadReferences();state.catalog=groupSymbols(refs.map((g,i)=>({...annotateSymbol(g,refs,state.profile),day:i+1}))).groups}state.catalog.forEach(matchProfile);state.catalogMode=true;goto(2);notice('Nur Dienste ohne vollständige Zuordnung werden angezeigt. Leere Felder gelten als frei.')}catch(e){notice(e.message,'error')}}
function closeCatalog(){state.catalogMode=false;state.maxStep=state.rect?1:0;goto(state.rect?1:0)}
const catalogButton=document.createElement('button');catalogButton.className='secondary';catalogButton.textContent='Alle Dienstsymbole definieren';catalogButton.id='catalog-button';catalogButton.onclick=openCatalog;const catalogCard=document.createElement('div');catalogCard.className='panel catalog-entry';catalogCard.innerHTML='<div><span class="label">EURE GEMEINSAME LEGENDE</span><h3>Alle Symbole aus dem Musterplan</h3><p>76 Bildvarianten sind vorbereitet. Trage die Bedeutungen und Dienstzeiten einmal ein.</p></div>';catalogCard.append(catalogButton);$('#panel-0').insertBefore(catalogCard,$('.mini-grid'));
function entries(){return state.cells.map(c=>{const g=state.groups.find(g=>g.id===(state.overrides[c.cellKey||c.day]||c.groupId));return{...c,definition:g?.definition,selectedId:g?.id,zgksId:g?.zgksId,serviceKey:g?.serviceKey,strokeCode:g?.strokeCode}})}
function renderReview(){const note=$('#zgks-review-note');note.hidden=!zgks.enabled;note.textContent=year()>=2027?'ZGKS-Legende aktiv · Offizielle PEP-Zeiten ab 2027. Prüfe besonders Zeiten, Abteilung und Zusätze.':'ZGKS-Legende aktiv. Für diesen älteren Plan wurden vorhandene Zuordnungen oder ausdrücklich ausgewählte Legendenzeiten verwendet. Bitte am Original prüfen.';const list=entries();const shifts=list.filter(e=>e.definition?.type==='shift');const all=list.filter(e=>e.definition?.type!=='skip');const minutes=shifts.reduce((n,e)=>n+shiftMinutes(e.definition),0);$('#summary').innerHTML=`<article class="summary-card"><span>${MONTHS[month()-1]} ${year()}</span><strong>${shifts.length}<small>Dienste</small></strong></article><article class="summary-card"><span>Zeitspanne ohne Pausenabzug</span><strong>${(minutes/60).toLocaleString('de-CH',{maximumFractionDigits:1})}<small>Std.</small></strong></article><article class="summary-card"><span>Für deinen Kalender</span><strong>${all.length}<small>Termine</small></strong></article>`;$('#demo-warning').hidden=!state.isDemo;$('#review-description').textContent=`${MONTHS[month()-1]} ${year()} · Prüfe jeden Tag am Original. Einzelne Dienste kannst du hier ändern.`;const body=$('#review-rows');body.innerHTML='';for(const e of list){const tr=document.createElement('tr');const date=new Date(Date.UTC(year(),month()-1,e.day));const weekday=new Intl.DateTimeFormat('de-CH',{weekday:'short',timeZone:'UTC'}).format(date);if([0,6].includes(date.getUTCDay()))tr.className='weekend';if(!validateDefinition(e.definition))tr.classList.add('unresolved');const td=document.createElement('td');td.innerHTML=`${pad(e.day)}.${pad(month())}.<span class="date-day">${weekday}</span>${e.partCount>1?'<small class="date-day">Eintrag '+e.partIndex+' von '+e.partCount+'</small>':''}`;tr.append(td);const imtd=document.createElement('td'),im=new Image();im.src=e.thumb;im.alt='Originalsymbol vom '+e.day+'.';imtd.append(im);tr.append(imtd);const choose=document.createElement('td'),sel=document.createElement('select');sel.setAttribute('aria-label',`Dienst am ${e.day}. ${MONTHS[month()-1]}${e.partCount>1?' Eintrag '+e.partIndex:''} ändern`);for(const g of state.groups){if(!validateDefinition(g.definition)||(e.partCount>1?(g.partialDate!==e.partialDate||g.partIndex!==e.partIndex||g.partCount!==e.partCount):g.partCount>1))continue;sel.add(new Option(g.definition.code+' · '+g.definition.name+(g.definition.department?' · '+g.definition.department:'')+(g.supplementLabels?.length?' · '+g.supplementLabels.join(' / '):''),g.id))}sel.value=e.selectedId;sel.onchange=()=>{state.overrides[e.cellKey||e.day]=sel.value;$('#confirmed').checked=false;renderReview()};choose.append(sel);tr.append(choose);const timed=document.createElement('td');const d=e.definition;timed.textContent=!validateDefinition(d)?'Noch offen':d.type==='skip'?'Kein Eintrag':d.type==='allday'?'Ganztägig':`${d.start}–${d.end}${d.end<d.start?' (+1 Tag)':''}`;if(e.note||departmentForEntry(e)){const note=document.createElement('small');note.className='cell-note';note.textContent=[departmentForEntry(e),e.note].filter(Boolean).join(' · ');timed.append(note)}tr.append(timed);body.append(tr)}updateExport()}
function exportAllowed(){return $('#confirmed').checked&&entries().every(e=>validateDefinition(e.definition))&&entries().some(e=>e.definition?.type!=='skip')}
