function saveZGKSSettings(){try{localStorage.setItem(ZGKS_SETTINGS_KEY,JSON.stringify(zgks))}catch{}}
function updateZGKSUI(){
 $('#zgks-enabled').checked=zgks.enabled;$('#zgks-settings').hidden=!zgks.enabled;
 catalogButton.textContent=zgks.enabled?'ZGKS-Legende ansehen':'Alle Dienstsymbole definieren';
 catalogCard.querySelector('h3').textContent=zgks.enabled?'ZGKS-Legende ist hinterlegt':'Alle Symbole aus dem Musterplan';
 catalogCard.querySelector('p').textContent=zgks.enabled?'54 offizielle Symbole und die bestätigten Stroke-Dienste mit Namen und Zeiten.':'76 Bildvarianten sind vorbereitet. Trage die Bedeutungen und Dienstzeiten einmal ein.';
}
function openZGKSLegend(){
 const rows=$('#zgks-legend-rows');rows.innerHTML='';
 for(const ref of [...zgksRegistry.symbols,...strokeLegend(zgksRegistry)]){const tr=document.createElement('tr'),imageCell=document.createElement('td'),img=new Image();img.src=ref.thumb;img.alt='ZGKS-Symbol '+ref.code;imageCell.append(img);tr.append(imageCell);const name=document.createElement('td');name.textContent=ref.name;tr.append(name);const time=document.createElement('td');time.textContent=ref.type==='skip'?'Kein Eintrag':ref.type==='allday'?'Ganztägig':ref.start+'–'+ref.end+(ref.end<ref.start?' (+1 Tag)':'');tr.append(time);rows.append(tr)}
 $('#zgks-legend-dialog').showModal();
}
$('#zgks-view-legend').onclick=openZGKSLegend;
for(const id of ['zgks-close-legend','zgks-legend-ok'])$('#'+id).onclick=()=>$('#zgks-legend-dialog').close();
$('#zgks-enabled').onchange=async()=>{
 zgks.enabled=$('#zgks-enabled').checked;saveZGKSSettings();updateZGKSUI();$('#confirmed').checked=false;state.catalog=[];
 if(state.cells.length&&state.rect)await analyse();else{updateExport();notice(zgks.enabled?'ZGKS-Legende aktiviert.':'Eigene Dienstlegende aktiviert.');}
};

updateZGKSUI();
